script:
// ---- Eye CRM desk helpers (the same block opens every Eye Client Script; the newest wins) ----
// Eye checks its own stages on the server (eye.pricing, eye.billing); these helpers show what a
// move needs and offer the dialogs that fix it. Buttons in messages follow the data-nx-action
// convention, so they work with or without Nexlify Board installed.
(() => {
	const VERSION = 6;
	if (window.eye_crm && window.eye_crm.version >= VERSION) return;
	const E = (window.eye_crm = { version: VERSION });

	E.STAGES = ["Estimation", "Proposal", "Quotation", "Project Won", "Accounts, please approve", "Quote approved"];
	E.WON = ["Project Won", "Accounts, please approve", "Quote approved"];
	E.ACCOUNTS_STAGE = "Accounts, please approve";
	E.APPROVED_STAGE = "Quote approved";
	E.BILLING_STAGES = ["To be invoiced", "Finance, please issue", "Invoiced", "Collected"];

	E.call = (method, op, args = {}, opts = {}) =>
		frappe.call({ method, args: { op, ...args }, ...opts }).then((r) => r.message && r.message.result);
	E.api = (op, args, opts) => E.call("eye.pricing", op, args, opts);
	E.billing = (op, args, opts) => E.call("eye.billing", op, args, opts);
	E.money = (v, cur) => format_currency(flt(v), cur);
	E.esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
	E.is_sales = () => frappe.user.has_role(["Sales User", "Sales Manager"]);
	E.is_accounts = () => frappe.user.has_role(["Accounts User", "Accounts Manager", "Sales Manager", "System Manager"]);
	E.is_finance = () => frappe.user.has_role(["Accounts User", "Accounts Manager", "System Manager"]);
	E.refresh = () => {
		if (window.cur_frm && !cur_frm.is_new()) return cur_frm.reload_doc();
		window.cur_list?.board?.refresh?.();
		window.cur_list?.refresh?.();
	};

	// ---- action buttons: <button data-nx-action="NAME" data-doctype=".." data-name="..">
	window.nx_actions = window.nx_actions || {};
	const ctx_of = (el) => {
		const frm = window.cur_frm;
		const moving = window.nx_action_context;
		const doctype = el?.dataset.doctype || moving?.doctype || frm?.doctype;
		const name = el?.dataset.name || moving?.name || frm?.docname;
		const form = frm && frm.doctype === doctype && frm.docname === name ? frm : null;
		return { doctype, name, frm: form, refresh: E.refresh };
	};
	if (!window.nx_run_action) {
		window.nx_run_action = (action, ctx) => {
			action = (action || "").trim();
			if (!action) return;
			if (action === "form") return frappe.set_route("Form", ctx.doctype, ctx.name);
			if (action.startsWith("route:")) return frappe.set_route(action.slice(6).replace(/^\/app\//, ""));
			if (action.startsWith("map:")) {
				const method = action.slice(4);
				return ctx.frm
					? frappe.model.open_mapped_doc({ method, frm: ctx.frm })
					: frappe.model.open_mapped_doc({ method, source_name: ctx.name });
			}
			const fn = window.nx_actions[action];
			if (!fn) return frappe.set_route("Form", ctx.doctype, ctx.name);
			return fn(ctx);
		};
	}
	if (!window.__nx_action_click) {
		window.__nx_action_click = true;
		$(document).on("click", "[data-nx-action]", function (e) {
			e.preventDefault();
			const ctx = ctx_of(this);
			$(this).closest(".modal").modal("hide");
			window.nx_run_action(this.dataset.nxAction, ctx);
		});
	}
	Object.assign(window.nx_actions, {
		requirements: (ctx) => (ctx.frm ? ctx.frm.scroll_to_field("custom_requirements") : E.requirements_dialog(ctx.name, ctx.refresh)),
		margin: (ctx) => (ctx.frm ? ctx.frm.scroll_to_field("custom_costing") : E.margin_dialog(ctx.name, ctx.refresh)),
		invoice: (ctx) => E.invoiced_dialog(ctx.name, ctx.refresh),
		collected: (ctx) => E.collected_dialog(ctx.name, ctx.refresh),
	});

	// ---- a blocked move (Nexlify Board shows its own screen when it is installed)
	E.steps_html = (doctype, name, missing) => {
		const rows = missing
			.map((s) => `<li>${E.esc(s.label)}${s.waiting_on ? ` <span class="text-muted">(${__("waiting on {0}", [E.esc(s.waiting_on)])})</span>` : ""}</li>`)
			.join("");
		const first = missing.find((s) => s.action && !s.waiting_on);
		const button = first
			? `<button class="btn btn-xs btn-primary" data-nx-action="${E.esc(first.action)}" data-doctype="${E.esc(doctype)}" data-name="${E.esc(name)}">${E.esc(first.action_label || __("Open"))}</button>`
			: "";
		return `<ul>${rows}</ul>${button}`;
	};
	E.blocked = (doctype, name, to, html) => {
		window.nx_action_context = { doctype, name };
		frappe.msgprint({ title: __("Can't move to {0} yet", [__(to)]), indicator: "red", message: html });
	};
	E.check_deal_move = async (name, to) => {
		const r = await E.api("stage_check", { name, to });
		if (!r.error && !(r.missing || []).length) return true;
		E.blocked("Opportunity", name, to, r.message || E.esc(r.error));
		return false;
	};

	// ---- Accounts' answer
	E.approve_dialog = (name, after) =>
		frappe.prompt(
			{ fieldtype: "Small Text", fieldname: "note", label: __("Note (optional)") },
			(v) =>
				E.api("approve_project", { name, note: v.note }, { freeze: true }).then((r) => {
					frappe.show_alert({
						message: r.sales_order ? __("Approved: Sales Order {0}", [r.sales_order]) : __("Approved"),
						indicator: "green",
					});
					if (r.error) frappe.msgprint({ title: __("Sales Order not created"), indicator: "orange", message: E.esc(r.error) });
					after && after();
				}),
			__("Approve the project"),
			__("Approve")
		);
	E.reject_dialog = (name, after) =>
		frappe.prompt(
			{ fieldtype: "Small Text", fieldname: "reason", label: __("Why isn't it approved?"), reqd: 1 },
			(v) =>
				E.api("reject_project", { name, reason: v.reason }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Sent back to Project Won"), indicator: "orange" });
					after && after();
				}),
			__("Send back to Sales"),
			__("Send Back")
		);
	E.retry_sales_order = (name, after) =>
		E.api("make_sales_order", { name }, { freeze: true }).then((so) => {
			frappe.show_alert({ message: __("Sales Order {0}", [so]), indicator: "green" });
			after && after();
		});

	// ---- invoices
	E.request_invoice_dialog = async (opportunity, after) => {
		const so = await E.billing("so_lines", { opportunity });
		const rows = so.rows.filter((r) => r.left > 0.0001).map((r) => ({ ...r, bill: r.left }));
		if (!rows.length) return frappe.msgprint(__("Everything on Sales Order {0} is already requested.", [so.sales_order]));
		const d = new frappe.ui.Dialog({
			title: __("Request an invoice"),
			size: "large",
			fields: [
				{ fieldtype: "Date", fieldname: "expected_date", label: __("Expected invoice date"), reqd: 1, default: frappe.datetime.get_today() },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes for Finance") },
				{ fieldtype: "Section Break", label: __("Items from {0}", [so.sales_order]) },
				{
					fieldtype: "Table",
					fieldname: "rows",
					in_place_edit: true,
					cannot_add_rows: true,
					data: rows,
					fields: [
						{ fieldtype: "Data", fieldname: "so_detail", hidden: 1 },
						{ fieldtype: "Data", fieldname: "item_name", label: __("Item"), in_list_view: 1, columns: 3, read_only: 1 },
						{ fieldtype: "Data", fieldname: "service_type", label: __("Service Type"), in_list_view: 1, columns: 2, read_only: 1 },
						{ fieldtype: "Float", fieldname: "left", label: __("Left"), in_list_view: 1, columns: 1, read_only: 1 },
						{ fieldtype: "Currency", fieldname: "rate", label: __("Rate"), in_list_view: 1, columns: 2, read_only: 1 },
						{ fieldtype: "Float", fieldname: "bill", label: __("To bill"), in_list_view: 1, columns: 2 },
					],
				},
			],
			primary_action_label: __("Request"),
			primary_action(v) {
				const picked = (v.rows || []).filter((r) => flt(r.bill) > 0).map((r) => ({ so_detail: r.so_detail, qty: r.bill }));
				E.billing("create", { opportunity, rows: JSON.stringify(picked), expected_date: v.expected_date, notes: v.notes }, { freeze: true }).then(
					(br) => {
						d.hide();
						frappe.show_alert({ message: __("Billing request {0}", [br]), indicator: "green" });
						after && after(br);
					}
				);
			},
		});
		d.show();
	};
	E.invoiced_dialog = (name, after) =>
		frappe.prompt(
			[
				{ fieldtype: "Data", fieldname: "invoice_number", label: __("Invoice number"), reqd: 1 },
				{ fieldtype: "Date", fieldname: "invoice_date", label: __("Invoice date"), reqd: 1, default: frappe.datetime.get_today() },
			],
			(v) =>
				E.billing("mark_invoiced", { name, ...v }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Invoiced"), indicator: "green" });
					after && after();
				}),
			__("Invoice issued"),
			__("Save")
		);
	E.collected_dialog = (name, after) =>
		frappe.prompt(
			[
				{ fieldtype: "Date", fieldname: "collected_on", label: __("Collected on"), reqd: 1, default: frappe.datetime.get_today() },
				{ fieldtype: "Currency", fieldname: "amount", label: __("Amount (empty: the full invoice)") },
			],
			(v) =>
				E.billing("mark_collected", { name, ...v }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Collected"), indicator: "green" });
					after && after();
				}),
			__("Payment received"),
			__("Save")
		);

	// ---- card badges (Kanban v2)
	E.badge_row = (badges) => {
		const row = document.createElement("div");
		row.className = "flex flex-wrap items-center gap-1 mt-2";
		badges.filter((b) => b && b.label).forEach((b) => {
			const el = frappe.ui.badge({ label: b.label, theme: b.theme || "gray", variant: b.variant, size: "sm" })[0];
			if (b.tooltip) frappe.ui.tooltip(el, { text: b.tooltip });
			row.appendChild(el);
		});
		return row;
	};
	E.board_field = (() => {
		const cache = {};
		return (board) => {
			if (!board) return Promise.resolve(null);
			cache[board] = cache[board] || frappe.db.get_value("Kanban Board", board, "field_name").then((r) => r.message?.field_name);
			return cache[board];
		};
	})();

	// the PL is drawn on the server (eye.pricing pl_view), so the form shows the same screen
	E.pl_dialog = async function (name) {
		const r = await E.api("pl_view", { name });
		return new Promise((resolve) => {
			let done = false;
			const d = new frappe.ui.Dialog({
				title: __("PL before Project Won"),
				size: "extra-large",
				primary_action_label: __("Confirm → Project Won"),
				primary_action() {
					done = true;
					d.hide();
					resolve(true);
				},
				secondary_action_label: __("Cancel"),
				secondary_action: () => d.hide(),
				onhide: () => {
					if (!done) resolve(false);
				},
			});
			$(d.body).html(r.html);
			d.show();
		});
	};

	E.requirements_dialog = async function (name, after) {
		const p = await E.api("get_pricing", { name });
		const locked = p.requirements.filter((r) => r.locked).length;
		const d = new frappe.ui.Dialog({
			title: __("Pricing Requirements"),
			size: "large",
			fields: [
				{ fieldtype: "HTML", fieldname: "info" },
				{ fieldtype: "Date", fieldname: "required_by", label: __("Required By"), default: p.required_by },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes for Production"), default: p.notes },
				{ fieldtype: "Section Break" },
				{
					fieldtype: "Table",
					fieldname: "rows",
					label: __("Requirements"),
					in_place_edit: true,
					data: p.requirements,
					fields: [
						{ fieldtype: "Data", fieldname: "name", hidden: 1 },
						{ fieldtype: "Link", fieldname: "item_code", label: __("Sales Item"), options: "Item", in_list_view: 1, columns: 2 },
						{ fieldtype: "Small Text", fieldname: "description", label: __("Description"), in_list_view: 1, columns: 3, reqd: 1 },
						{ fieldtype: "Float", fieldname: "qty", label: __("Qty"), in_list_view: 1, columns: 1, default: 1 },
						{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes"), in_list_view: 1, columns: 3 },
					],
				},
			],
			primary_action_label: p.open ? __("Save") : __("Save & Send to Production"),
			primary_action(v) {
				save(v, p.open ? 0 : 1);
			},
			secondary_action_label: p.open ? null : __("Save only"),
			secondary_action: p.open ? null : () => save(d.get_values(true), 0),
		});
		const msgs = [];
		if (p.status) msgs.push(__("Pricing status: {0}", [__(p.status)]));
		if (locked) msgs.push(__("{0} line(s) are already with Production; to change them use Request Change in the deal.", [locked]));
		d.fields_dict.info.$wrapper.html(msgs.map((m) => `<div class="text-muted small">${frappe.utils.escape_html(m)}</div>`).join(""));

		function save(v, send) {
			if (send && !v.required_by) {
				frappe.msgprint(__("Set Required By first."));
				return;
			}
			E.api("save_requirements", { name, rows: JSON.stringify(v.rows || []), required_by: v.required_by, notes: v.notes, send }).then(
				(pr) => {
					d.hide();
					frappe.show_alert({ message: pr ? __("Sent to Production: {0}", [pr]) : __("Saved"), indicator: "green" });
					after && after();
				}
			);
		}
		d.show();
	};

	E.margin_dialog = async function (name, after) {
		const p = await E.api("get_pricing", { name });
		const d = new frappe.ui.Dialog({
			title: __("Set Margin"),
			size: "large",
			fields: [
				{
					fieldtype: "Percent",
					fieldname: "default_margin",
					label: __("Margin for all lines %"),
					default: p.default_margin,
					onchange() {
						const m = d.get_value("default_margin");
						if (m === null || m === undefined || m === "") return;
						d.fields_dict.rows.df.data.forEach((r) => (r.margin = m));
						d.fields_dict.rows.grid.refresh();
						summary();
					},
				},
				{ fieldtype: "Section Break" },
				{
					fieldtype: "Table",
					fieldname: "rows",
					label: __("Costing"),
					in_place_edit: true,
					cannot_add_rows: true,
					cannot_delete_rows: true,
					data: p.costing,
					fields: [
						{ fieldtype: "Data", fieldname: "name", hidden: 1 },
						{ fieldtype: "Small Text", fieldname: "description", label: __("Description"), in_list_view: 1, columns: 4, read_only: 1 },
						{ fieldtype: "Currency", fieldname: "cost", label: __("Cost"), in_list_view: 1, columns: 2, read_only: 1, options: "currency" },
						{ fieldtype: "Percent", fieldname: "margin", label: __("Margin %"), in_list_view: 1, columns: 2, onchange: () => summary() },
					],
				},
				{ fieldtype: "HTML", fieldname: "summary" },
			],
			primary_action_label: __("Save"),
			primary_action(v) {
				const margins = Object.fromEntries((v.rows || []).map((r) => [r.name, r.margin]));
				E.api("save_margins", { name, margins: JSON.stringify(margins), default_margin: v.default_margin }).then(() => {
					d.hide();
					frappe.show_alert({ message: __("Margin saved"), indicator: "green" });
					after && after();
				});
			},
		});
		function summary() {
			const rows = d.fields_dict.rows.df.data || [];
			const cost = rows.reduce((s, r) => s + flt(r.cost), 0);
			const min = rows.reduce((s, r) => s + flt(r.cost) * (1 + flt(r.margin) / 100), 0);
			const ok = p.items_total + 0.005 >= min;
			d.fields_dict.summary.$wrapper.html(`<div class="row text-center" style="margin-top:8px">
				<div class="col-sm-4"><div class="text-muted">${__("Total cost")}</div><h5>${E.money(cost, p.currency)}</h5></div>
				<div class="col-sm-4"><div class="text-muted">${__("Minimum selling")}</div><h5>${E.money(min, p.currency)}</h5></div>
				<div class="col-sm-4"><div class="text-muted">${__("Items total")}</div>
					<h5 style="color:${ok ? "var(--green-600)" : "var(--red-600)"}">${E.money(p.items_total, p.currency)}</h5></div></div>`);
		}
		d.show();
		summary();
	};

	E.make_quotation = function (name) {
		frappe.model.open_mapped_doc({ method: "erpnext.crm.doctype.opportunity.opportunity.make_quotation", source_name: name });
	};
})();

// ---- Eye CRM · Opportunity form: pricing, Accounts' answer, invoice requests, PL before Won.
// Rules run on the server in the "eye.pricing" Server Script; a stage change is checked as soon
// as it is picked (stage_check), and again on save.
(() => {
	const E = window.eye_crm;
	const WON = E.WON;
	const OPEN = ["With Production", "In Pricing", "Returned to Sales", "Change Requested"];
	const api = E.api;
	const is_sales = E.is_sales;

	// section headers: a little bigger, with a line under them (the look only; the sections,
	// their order and collapsing are set in Customize Form)
	if (!document.getElementById("eye-form-sections")) {
		$(`<style id="eye-form-sections">
			.eye-opp-form .form-section{border:1px solid var(--border-color);border-radius:12px;margin:0 24px 18px;
				padding:18px 26px 8px;background:var(--card-bg);box-shadow:0 1px 2px rgba(15,23,42,.04)}
			.eye-opp-form .form-section .section-head{margin:0;padding:0;font-size:17px;font-weight:650;letter-spacing:-.01em;
				background:none;border:none}
			.eye-opp-form .form-section .section-head .collapse-indicator{margin-left:auto}
			.eye-opp-form .form-section .section-description{font-size:12px;color:var(--text-muted);margin:2px 0 14px;padding:0}
			.eye-opp-form .form-section .section-head:not(.collapsed)+.section-body,
			.eye-opp-form .form-section .section-description+.section-body{margin-top:12px}
			.eye-opp-form .form-section .section-body{padding:0}
		</style>`).appendTo(document.head);
	}
	frappe.ui.form.on("Opportunity", "refresh", (frm) => {
		if (frm.wrapper instanceof HTMLElement) frm.wrapper.classList.add("eye-opp-form");
	});

	frappe.ui.form.on("Opportunity", {
		refresh(frm) {
			const sales = is_sales();
			const st = frm.doc.custom_pricing_status;
			frm.__eye_prev_stage = frm.doc.sales_stage;

			frm.fields_dict.custom_costing.grid.update_docfield_property("margin", "read_only", sales ? 0 : 1);
			frm.set_df_property("custom_costing", "cannot_add_rows", 1);
			frm.set_df_property("custom_costing", "cannot_delete_rows", 1);
			frm.toggle_display(["custom_costing_sb", "custom_costing_table_sb"], (frm.doc.custom_costing || []).length > 0);

			render_summary(frm);
			if (frm.is_new()) return;

			const alerts = {
				Priced: [__("Pricing: Priced ✓"), "green"],
				"With Production": [__("Pricing: sent, Production has not started yet (you can still edit the requirements)"), "blue"],
				"In Pricing": [__("Pricing: Production is pricing"), "red"],
				"Returned to Sales": [__("Pricing: Production has a question, open the Pricing Request"), "orange"],
				"Change Requested": [__("Pricing: Production is changing the costs"), "orange"],
			};
			if (alerts[st]) frm.dashboard.set_headline_alert(...alerts[st]);

			const priced = new Set((frm.doc.custom_costing || []).map((c) => c.requirement));
			const to_price = (frm.doc.custom_requirements || []).filter((r) => !priced.has(r.name)).length;
			if (sales && !OPEN.includes(st) && to_price) {
				frm.add_custom_button(__("Send to Production"), () => send(frm)).addClass("btn-primary");
			}

			api("get_state", { opportunity: frm.doc.name }).then((s) => {
				frm.__eye_locked = new Set(s.locked || []);
				if (sales && frm.__eye_locked.size) {
					frm.add_custom_button(__("Request Change"), () => request_change(frm), __("Pricing"));
				}
				(s.pending || []).forEach((p) => {
					const link = `<a href="/app/pricing-change/${encodeURIComponent(p.name)}">${p.name}</a>`;
					const msg =
						p.requested_by_side !== "Production"
							? __("Your change request {0} is waiting for Production", [link])
							: p.status === "Requested"
							? __("Production asks to change the costs: allow or reject in {0}", [link])
							: __("Production changed the costs: review and approve {0}", [link]);
					frm.dashboard.add_comment(msg, p.requested_by_side === "Production" ? "orange" : "blue", true);
				});
			});
			render_requests(frm);
			deal_buttons(frm);
			render_billing(frm);
		},

		custom_default_margin(frm) {
			(frm.doc.custom_costing || []).forEach((r) => {
				frappe.model.set_value(r.doctype, r.name, "margin", frm.doc.custom_default_margin);
			});
		},

		items_remove: (frm) => render_summary(frm),

		// a picked stage is checked at once; Project Won then shows the PL
		async sales_stage(frm) {
			const prev = frm.__eye_prev_stage;
			const to = frm.doc.sales_stage;
			if (frm.is_new() || !to || to === prev || frm.__eye_reverting) return;
			const revert = () => {
				frm.__eye_reverting = true;
				frm.set_value("sales_stage", prev).then(() => (frm.__eye_reverting = false));
			};
			if (!(await E.check_deal_move(frm.doc.name, to))) return revert();
			if (to === "Project Won" && !WON.includes(prev)) show_pl(frm, () => frm.save(), revert);
		},
	});

	frappe.ui.form.on("Opportunity Costing", {
		margin(frm, cdt, cdn) {
			const r = locals[cdt][cdn];
			frappe.model.set_value(cdt, cdn, "selling", flt(r.cost) * (1 + flt(r.margin) / 100));
			let cost = 0;
			let selling = 0;
			(frm.doc.custom_costing || []).forEach((c) => {
				cost += flt(c.cost);
				selling += flt(c.selling);
			});
			frm.set_value("custom_total_cost", cost);
			frm.set_value("custom_total_selling", selling);
			render_summary(frm);
		},
	});

	frappe.ui.form.on("Opportunity Item", {
		qty: (frm) => setTimeout(() => render_summary(frm), 300),
		rate: (frm) => setTimeout(() => render_summary(frm), 300),
		amount: (frm) => render_summary(frm),
	});

	function items_total(frm) {
		return (frm.doc.items || []).reduce((s, i) => s + (flt(i.amount) || flt(i.qty) * flt(i.rate)), 0);
	}

	function render_summary(frm) {
		const wrap = frm.fields_dict.custom_costing_summary && frm.fields_dict.custom_costing_summary.$wrapper;
		if (!wrap) return;
		if (!(frm.doc.custom_costing || []).length) {
			wrap.html("");
			return;
		}
		const fmt = (v) => format_currency(v, frm.doc.currency);
		const items = items_total(frm);
		const min = flt(frm.doc.custom_total_selling);
		const gap = items - min;
		const ok = gap >= -0.005;
		wrap.html(`
			<div class="row text-center" style="margin-top:8px">
				<div class="col-sm-4"><div class="text-muted">${__("Minimum selling total")}</div><h4>${fmt(min)}</h4></div>
				<div class="col-sm-4"><div class="text-muted">${__("Items total")}</div><h4>${fmt(items)}</h4></div>
				<div class="col-sm-4"><div class="text-muted">${ok ? __("Above minimum by") : __("Below minimum by")}</div>
					<h4 style="color:${ok ? "var(--green-600)" : "var(--red-600)"}">${fmt(Math.abs(gap))}</h4></div>
			</div>`);
	}

	function send(frm) {
		if (frm.is_dirty()) {
			frappe.msgprint(__("Save the Opportunity first."));
			return;
		}
		if (!frm.doc.custom_pricing_required_by) {
			frappe.msgprint(__("Set Required By in the Pricing tab first."));
			frm.scroll_to_field("custom_pricing_required_by");
			return;
		}
		api("send_to_production", { opportunity: frm.doc.name }, { freeze: true, freeze_message: __("Sending to Production...") }).then(
			(pr) => {
				const link = `<a href="/app/pricing-request/${encodeURIComponent(pr)}">${pr}</a>`;
				frappe.show_alert({ message: __("Sent to Production: {0}", [link]), indicator: "green" }, 8);
				frm.reload_doc();
			}
		);
	}

	function render_requests(frm) {
		const wrap = frm.fields_dict.custom_pricing_requests_html && frm.fields_dict.custom_pricing_requests_html.$wrapper;
		if (!wrap) return;
		frappe.db
			.get_list("Pricing Request", {
				filters: { opportunity: frm.doc.name },
				fields: ["name", "status", "required_by", "total_cost", "currency", "creation"],
				order_by: "creation desc",
				limit: 50,
			})
			.then((rows) => {
				if (!rows.length) {
					wrap.html(`<div class="text-muted">${__("No pricing requests yet.")}</div>`);
					return;
				}
				const colors = {
					"With Production": "blue",
					"In Pricing": "orange",
					"Returned to Sales": "yellow",
					"Change Requested": "yellow",
					Priced: "green",
				};
				const body = rows
					.map(
						(r) => `<tr>
					<td><a href="/app/pricing-request/${encodeURIComponent(r.name)}">${r.name}</a></td>
					<td><span class="indicator-pill ${colors[r.status] || "orange"}">${__(r.status || "With Production")}</span></td>
					<td>${frappe.datetime.str_to_user(r.required_by) || ""}</td>
					<td class="text-right">${r.status === "Priced" ? format_currency(r.total_cost, r.currency) : ""}</td>
					<td>${frappe.datetime.str_to_user(r.creation)}</td>
				</tr>`
					)
					.join("");
				wrap.html(`<table class="table table-bordered table-sm">
				<thead><tr><th>${__("Request")}</th><th>${__("Status")}</th><th>${__("Required By")}</th>
				<th class="text-right">${__("Total Cost")}</th><th>${__("Sent On")}</th></tr></thead>
				<tbody>${body}</tbody></table>`);
			});
	}

	// the same PL screen as the Kanban, drawn by eye.pricing pl_view
	async function show_pl(frm, on_confirm, on_cancel) {
		const r = await api("pl_view", { name: frm.doc.name });
		let done = false;
		const d = new frappe.ui.Dialog({
			title: __("PL before Project Won"),
			size: "extra-large",
			primary_action_label: __("Confirm → Project Won"),
			primary_action() {
				done = true;
				d.hide();
				on_confirm();
			},
			secondary_action_label: __("Cancel"),
			secondary_action: () => d.hide(),
		});
		d.onhide = () => {
			if (!done) on_cancel();
		};
		$(d.body).html(r.html);
		d.show();
	}

	function request_change(frm) {
		const short = (t) => String(t || "").replace(/\s+/g, " ").trim().slice(0, 50);
		const rows = (frm.doc.custom_requirements || []).filter((r) => frm.__eye_locked.has(r.name));
		const opts = rows.map((r) => `${r.idx} · ${short(r.description)}`);
		const pick = (v) => rows[opts.indexOf(v)];
		const d = new frappe.ui.Dialog({
			title: __("Request Change"),
			fields: [
				{
					fieldtype: "Select",
					fieldname: "line",
					label: __("Requirement"),
					options: opts,
					reqd: 1,
					onchange() {
						const r = pick(d.get_value("line"));
						if (r) d.set_values({ description: r.description, qty: r.qty, notes: r.notes });
					},
				},
				{ fieldtype: "Small Text", fieldname: "description", label: __("New Description"), reqd: 1 },
				{ fieldtype: "Float", fieldname: "qty", label: __("New Qty") },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("New Notes") },
				{ fieldtype: "Small Text", fieldname: "reason", label: __("Reason"), reqd: 1 },
			],
			primary_action_label: __("Send to Production"),
			primary_action(v) {
				api(
					"request_requirement_change",
					{
						opportunity: frm.doc.name,
						requirement: pick(v.line).name,
						reason: v.reason,
						description: v.description,
						qty: v.qty,
						notes: v.notes,
					},
					{ freeze: true }
				).then(() => {
					d.hide();
					frm.reload_doc();
				});
			},
		});
		d.show();
		if (opts.length) d.set_value("line", opts[0]);
	}

	function deal_buttons(frm) {
		const d = frm.doc;
		const after = () => frm.reload_doc();
		if (d.sales_stage === E.ACCOUNTS_STAGE) {
			frm.dashboard.set_headline_alert(__("Waiting for Accounts to approve the project"), "orange");
			if (E.is_accounts()) {
				frm.add_custom_button(__("Approve Project"), () => E.approve_dialog(d.name, after), __("Accounts")).addClass("btn-primary");
				frm.add_custom_button(__("Send Back to Sales"), () => E.reject_dialog(d.name, after), __("Accounts"));
			}
		}
		if (d.custom_accounts_approval === "Rejected" && d.sales_stage === "Project Won") {
			frm.dashboard.set_headline_alert(__("Accounts sent it back: {0}", [E.esc(d.custom_approval_note)]), "red");
		}
		if (d.sales_stage === E.APPROVED_STAGE) {
			if (d.custom_sales_order && is_sales()) {
				frm.add_custom_button(__("Request Invoice"), () => E.request_invoice_dialog(d.name, after)).addClass("btn-primary");
			}
			if (!d.custom_sales_order) {
				frm.add_custom_button(__("Create Sales Order"), () => E.retry_sales_order(d.name, after));
			}
		}
	}

	function render_billing(frm) {
		const field = frm.fields_dict.custom_billing_html;
		if (!field || frm.is_new()) return;
		frappe.db
			.get_list("Billing Request", {
				filters: { opportunity: frm.doc.name },
				fields: ["name", "billing_stage", "expected_date", "total", "currency", "invoice_number", "collected_amount"],
				order_by: "creation asc",
				limit: 100,
			})
			.then((rows) => {
				if (!rows.length) return field.$wrapper.html(`<p class="text-muted">${__("No invoice requests yet.")}</p>`);
				const body = rows
					.map(
						(r) => `<tr><td><a href="/app/billing-request/${encodeURIComponent(r.name)}">${E.esc(r.name)}</a></td>
						<td>${E.esc(__(r.billing_stage))}</td><td>${E.esc(frappe.datetime.str_to_user(r.expected_date))}</td>
						<td class="text-right">${E.money(r.total, r.currency)}</td><td>${E.esc(r.invoice_number)}</td>
						<td class="text-right">${E.money(r.collected_amount, r.currency)}</td></tr>`
					)
					.join("");
				field.$wrapper.html(`<table class="table table-bordered table-sm"><thead><tr><th>${__("Request")}</th><th>${__("Stage")}</th>
					<th>${__("Expected")}</th><th class="text-right">${__("Total")}</th><th>${__("Invoice")}</th>
					<th class="text-right">${__("Collected")}</th></tr></thead><tbody>${body}</tbody></table>`);
			});
	}
})();

// ---- Eye CRM desk helpers (the same block opens every Eye Client Script; the newest wins) ----
// Eye checks its own stages on the server (eye.pricing, eye.billing); these helpers show what a
// move needs and offer the dialogs that fix it. Buttons in messages follow the data-nx-action
// convention, so they work with or without Nexlify Board installed.
(() => {
	const VERSION = 6;
	if (window.eye_crm && window.eye_crm.version >= VERSION) return;
	const E = (window.eye_crm = { version: VERSION });

	E.STAGES = ["Estimation", "Proposal", "Quotation", "Project Won", "Accounts, please approve", "Quote approved"];
	E.WON = ["Project Won", "Accounts, please approve", "Quote approved"];
	E.ACCOUNTS_STAGE = "Accounts, please approve";
	E.APPROVED_STAGE = "Quote approved";
	E.BILLING_STAGES = ["To be invoiced", "Finance, please issue", "Invoiced", "Collected"];

	E.call = (method, op, args = {}, opts = {}) =>
		frappe.call({ method, args: { op, ...args }, ...opts }).then((r) => r.message && r.message.result);
	E.api = (op, args, opts) => E.call("eye.pricing", op, args, opts);
	E.billing = (op, args, opts) => E.call("eye.billing", op, args, opts);
	E.money = (v, cur) => format_currency(flt(v), cur);
	E.esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
	E.is_sales = () => frappe.user.has_role(["Sales User", "Sales Manager"]);
	E.is_accounts = () => frappe.user.has_role(["Accounts User", "Accounts Manager", "Sales Manager", "System Manager"]);
	E.is_finance = () => frappe.user.has_role(["Accounts User", "Accounts Manager", "System Manager"]);
	E.refresh = () => {
		if (window.cur_frm && !cur_frm.is_new()) return cur_frm.reload_doc();
		window.cur_list?.board?.refresh?.();
		window.cur_list?.refresh?.();
	};

	// ---- action buttons: <button data-nx-action="NAME" data-doctype=".." data-name="..">
	window.nx_actions = window.nx_actions || {};
	const ctx_of = (el) => {
		const frm = window.cur_frm;
		const moving = window.nx_action_context;
		const doctype = el?.dataset.doctype || moving?.doctype || frm?.doctype;
		const name = el?.dataset.name || moving?.name || frm?.docname;
		const form = frm && frm.doctype === doctype && frm.docname === name ? frm : null;
		return { doctype, name, frm: form, refresh: E.refresh };
	};
	if (!window.nx_run_action) {
		window.nx_run_action = (action, ctx) => {
			action = (action || "").trim();
			if (!action) return;
			if (action === "form") return frappe.set_route("Form", ctx.doctype, ctx.name);
			if (action.startsWith("route:")) return frappe.set_route(action.slice(6).replace(/^\/app\//, ""));
			if (action.startsWith("map:")) {
				const method = action.slice(4);
				return ctx.frm
					? frappe.model.open_mapped_doc({ method, frm: ctx.frm })
					: frappe.model.open_mapped_doc({ method, source_name: ctx.name });
			}
			const fn = window.nx_actions[action];
			if (!fn) return frappe.set_route("Form", ctx.doctype, ctx.name);
			return fn(ctx);
		};
	}
	if (!window.__nx_action_click) {
		window.__nx_action_click = true;
		$(document).on("click", "[data-nx-action]", function (e) {
			e.preventDefault();
			const ctx = ctx_of(this);
			$(this).closest(".modal").modal("hide");
			window.nx_run_action(this.dataset.nxAction, ctx);
		});
	}
	Object.assign(window.nx_actions, {
		requirements: (ctx) => (ctx.frm ? ctx.frm.scroll_to_field("custom_requirements") : E.requirements_dialog(ctx.name, ctx.refresh)),
		margin: (ctx) => (ctx.frm ? ctx.frm.scroll_to_field("custom_costing") : E.margin_dialog(ctx.name, ctx.refresh)),
		invoice: (ctx) => E.invoiced_dialog(ctx.name, ctx.refresh),
		collected: (ctx) => E.collected_dialog(ctx.name, ctx.refresh),
	});

	// ---- a blocked move (Nexlify Board shows its own screen when it is installed)
	E.steps_html = (doctype, name, missing) => {
		const rows = missing
			.map((s) => `<li>${E.esc(s.label)}${s.waiting_on ? ` <span class="text-muted">(${__("waiting on {0}", [E.esc(s.waiting_on)])})</span>` : ""}</li>`)
			.join("");
		const first = missing.find((s) => s.action && !s.waiting_on);
		const button = first
			? `<button class="btn btn-xs btn-primary" data-nx-action="${E.esc(first.action)}" data-doctype="${E.esc(doctype)}" data-name="${E.esc(name)}">${E.esc(first.action_label || __("Open"))}</button>`
			: "";
		return `<ul>${rows}</ul>${button}`;
	};
	E.blocked = (doctype, name, to, html) => {
		window.nx_action_context = { doctype, name };
		frappe.msgprint({ title: __("Can't move to {0} yet", [__(to)]), indicator: "red", message: html });
	};
	E.check_deal_move = async (name, to) => {
		const r = await E.api("stage_check", { name, to });
		if (!r.error && !(r.missing || []).length) return true;
		E.blocked("Opportunity", name, to, r.message || E.esc(r.error));
		return false;
	};

	// ---- Accounts' answer
	E.approve_dialog = (name, after) =>
		frappe.prompt(
			{ fieldtype: "Small Text", fieldname: "note", label: __("Note (optional)") },
			(v) =>
				E.api("approve_project", { name, note: v.note }, { freeze: true }).then((r) => {
					frappe.show_alert({
						message: r.sales_order ? __("Approved: Sales Order {0}", [r.sales_order]) : __("Approved"),
						indicator: "green",
					});
					if (r.error) frappe.msgprint({ title: __("Sales Order not created"), indicator: "orange", message: E.esc(r.error) });
					after && after();
				}),
			__("Approve the project"),
			__("Approve")
		);
	E.reject_dialog = (name, after) =>
		frappe.prompt(
			{ fieldtype: "Small Text", fieldname: "reason", label: __("Why isn't it approved?"), reqd: 1 },
			(v) =>
				E.api("reject_project", { name, reason: v.reason }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Sent back to Project Won"), indicator: "orange" });
					after && after();
				}),
			__("Send back to Sales"),
			__("Send Back")
		);
	E.retry_sales_order = (name, after) =>
		E.api("make_sales_order", { name }, { freeze: true }).then((so) => {
			frappe.show_alert({ message: __("Sales Order {0}", [so]), indicator: "green" });
			after && after();
		});

	// ---- invoices
	E.request_invoice_dialog = async (opportunity, after) => {
		const so = await E.billing("so_lines", { opportunity });
		const rows = so.rows.filter((r) => r.left > 0.0001).map((r) => ({ ...r, bill: r.left }));
		if (!rows.length) return frappe.msgprint(__("Everything on Sales Order {0} is already requested.", [so.sales_order]));
		const d = new frappe.ui.Dialog({
			title: __("Request an invoice"),
			size: "large",
			fields: [
				{ fieldtype: "Date", fieldname: "expected_date", label: __("Expected invoice date"), reqd: 1, default: frappe.datetime.get_today() },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes for Finance") },
				{ fieldtype: "Section Break", label: __("Items from {0}", [so.sales_order]) },
				{
					fieldtype: "Table",
					fieldname: "rows",
					in_place_edit: true,
					cannot_add_rows: true,
					data: rows,
					fields: [
						{ fieldtype: "Data", fieldname: "so_detail", hidden: 1 },
						{ fieldtype: "Data", fieldname: "item_name", label: __("Item"), in_list_view: 1, columns: 3, read_only: 1 },
						{ fieldtype: "Data", fieldname: "service_type", label: __("Service Type"), in_list_view: 1, columns: 2, read_only: 1 },
						{ fieldtype: "Float", fieldname: "left", label: __("Left"), in_list_view: 1, columns: 1, read_only: 1 },
						{ fieldtype: "Currency", fieldname: "rate", label: __("Rate"), in_list_view: 1, columns: 2, read_only: 1 },
						{ fieldtype: "Float", fieldname: "bill", label: __("To bill"), in_list_view: 1, columns: 2 },
					],
				},
			],
			primary_action_label: __("Request"),
			primary_action(v) {
				const picked = (v.rows || []).filter((r) => flt(r.bill) > 0).map((r) => ({ so_detail: r.so_detail, qty: r.bill }));
				E.billing("create", { opportunity, rows: JSON.stringify(picked), expected_date: v.expected_date, notes: v.notes }, { freeze: true }).then(
					(br) => {
						d.hide();
						frappe.show_alert({ message: __("Billing request {0}", [br]), indicator: "green" });
						after && after(br);
					}
				);
			},
		});
		d.show();
	};
	E.invoiced_dialog = (name, after) =>
		frappe.prompt(
			[
				{ fieldtype: "Data", fieldname: "invoice_number", label: __("Invoice number"), reqd: 1 },
				{ fieldtype: "Date", fieldname: "invoice_date", label: __("Invoice date"), reqd: 1, default: frappe.datetime.get_today() },
			],
			(v) =>
				E.billing("mark_invoiced", { name, ...v }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Invoiced"), indicator: "green" });
					after && after();
				}),
			__("Invoice issued"),
			__("Save")
		);
	E.collected_dialog = (name, after) =>
		frappe.prompt(
			[
				{ fieldtype: "Date", fieldname: "collected_on", label: __("Collected on"), reqd: 1, default: frappe.datetime.get_today() },
				{ fieldtype: "Currency", fieldname: "amount", label: __("Amount (empty: the full invoice)") },
			],
			(v) =>
				E.billing("mark_collected", { name, ...v }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Collected"), indicator: "green" });
					after && after();
				}),
			__("Payment received"),
			__("Save")
		);

	// ---- card badges (Kanban v2)
	E.badge_row = (badges) => {
		const row = document.createElement("div");
		row.className = "flex flex-wrap items-center gap-1 mt-2";
		badges.filter((b) => b && b.label).forEach((b) => {
			const el = frappe.ui.badge({ label: b.label, theme: b.theme || "gray", variant: b.variant, size: "sm" })[0];
			if (b.tooltip) frappe.ui.tooltip(el, { text: b.tooltip });
			row.appendChild(el);
		});
		return row;
	};
	E.board_field = (() => {
		const cache = {};
		return (board) => {
			if (!board) return Promise.resolve(null);
			cache[board] = cache[board] || frappe.db.get_value("Kanban Board", board, "field_name").then((r) => r.message?.field_name);
			return cache[board];
		};
	})();

	// the PL is drawn on the server (eye.pricing pl_view), so the form shows the same screen
	E.pl_dialog = async function (name) {
		const r = await E.api("pl_view", { name });
		return new Promise((resolve) => {
			let done = false;
			const d = new frappe.ui.Dialog({
				title: __("PL before Project Won"),
				size: "extra-large",
				primary_action_label: __("Confirm → Project Won"),
				primary_action() {
					done = true;
					d.hide();
					resolve(true);
				},
				secondary_action_label: __("Cancel"),
				secondary_action: () => d.hide(),
				onhide: () => {
					if (!done) resolve(false);
				},
			});
			$(d.body).html(r.html);
			d.show();
		});
	};

	E.requirements_dialog = async function (name, after) {
		const p = await E.api("get_pricing", { name });
		const locked = p.requirements.filter((r) => r.locked).length;
		const d = new frappe.ui.Dialog({
			title: __("Pricing Requirements"),
			size: "large",
			fields: [
				{ fieldtype: "HTML", fieldname: "info" },
				{ fieldtype: "Date", fieldname: "required_by", label: __("Required By"), default: p.required_by },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes for Production"), default: p.notes },
				{ fieldtype: "Section Break" },
				{
					fieldtype: "Table",
					fieldname: "rows",
					label: __("Requirements"),
					in_place_edit: true,
					data: p.requirements,
					fields: [
						{ fieldtype: "Data", fieldname: "name", hidden: 1 },
						{ fieldtype: "Link", fieldname: "item_code", label: __("Sales Item"), options: "Item", in_list_view: 1, columns: 2 },
						{ fieldtype: "Small Text", fieldname: "description", label: __("Description"), in_list_view: 1, columns: 3, reqd: 1 },
						{ fieldtype: "Float", fieldname: "qty", label: __("Qty"), in_list_view: 1, columns: 1, default: 1 },
						{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes"), in_list_view: 1, columns: 3 },
					],
				},
			],
			primary_action_label: p.open ? __("Save") : __("Save & Send to Production"),
			primary_action(v) {
				save(v, p.open ? 0 : 1);
			},
			secondary_action_label: p.open ? null : __("Save only"),
			secondary_action: p.open ? null : () => save(d.get_values(true), 0),
		});
		const msgs = [];
		if (p.status) msgs.push(__("Pricing status: {0}", [__(p.status)]));
		if (locked) msgs.push(__("{0} line(s) are already with Production; to change them use Request Change in the deal.", [locked]));
		d.fields_dict.info.$wrapper.html(msgs.map((m) => `<div class="text-muted small">${frappe.utils.escape_html(m)}</div>`).join(""));

		function save(v, send) {
			if (send && !v.required_by) {
				frappe.msgprint(__("Set Required By first."));
				return;
			}
			E.api("save_requirements", { name, rows: JSON.stringify(v.rows || []), required_by: v.required_by, notes: v.notes, send }).then(
				(pr) => {
					d.hide();
					frappe.show_alert({ message: pr ? __("Sent to Production: {0}", [pr]) : __("Saved"), indicator: "green" });
					after && after();
				}
			);
		}
		d.show();
	};

	E.margin_dialog = async function (name, after) {
		const p = await E.api("get_pricing", { name });
		const d = new frappe.ui.Dialog({
			title: __("Set Margin"),
			size: "large",
			fields: [
				{
					fieldtype: "Percent",
					fieldname: "default_margin",
					label: __("Margin for all lines %"),
					default: p.default_margin,
					onchange() {
						const m = d.get_value("default_margin");
						if (m === null || m === undefined || m === "") return;
						d.fields_dict.rows.df.data.forEach((r) => (r.margin = m));
						d.fields_dict.rows.grid.refresh();
						summary();
					},
				},
				{ fieldtype: "Section Break" },
				{
					fieldtype: "Table",
					fieldname: "rows",
					label: __("Costing"),
					in_place_edit: true,
					cannot_add_rows: true,
					cannot_delete_rows: true,
					data: p.costing,
					fields: [
						{ fieldtype: "Data", fieldname: "name", hidden: 1 },
						{ fieldtype: "Small Text", fieldname: "description", label: __("Description"), in_list_view: 1, columns: 4, read_only: 1 },
						{ fieldtype: "Currency", fieldname: "cost", label: __("Cost"), in_list_view: 1, columns: 2, read_only: 1, options: "currency" },
						{ fieldtype: "Percent", fieldname: "margin", label: __("Margin %"), in_list_view: 1, columns: 2, onchange: () => summary() },
					],
				},
				{ fieldtype: "HTML", fieldname: "summary" },
			],
			primary_action_label: __("Save"),
			primary_action(v) {
				const margins = Object.fromEntries((v.rows || []).map((r) => [r.name, r.margin]));
				E.api("save_margins", { name, margins: JSON.stringify(margins), default_margin: v.default_margin }).then(() => {
					d.hide();
					frappe.show_alert({ message: __("Margin saved"), indicator: "green" });
					after && after();
				});
			},
		});
		function summary() {
			const rows = d.fields_dict.rows.df.data || [];
			const cost = rows.reduce((s, r) => s + flt(r.cost), 0);
			const min = rows.reduce((s, r) => s + flt(r.cost) * (1 + flt(r.margin) / 100), 0);
			const ok = p.items_total + 0.005 >= min;
			d.fields_dict.summary.$wrapper.html(`<div class="row text-center" style="margin-top:8px">
				<div class="col-sm-4"><div class="text-muted">${__("Total cost")}</div><h5>${E.money(cost, p.currency)}</h5></div>
				<div class="col-sm-4"><div class="text-muted">${__("Minimum selling")}</div><h5>${E.money(min, p.currency)}</h5></div>
				<div class="col-sm-4"><div class="text-muted">${__("Items total")}</div>
					<h5 style="color:${ok ? "var(--green-600)" : "var(--red-600)"}">${E.money(p.items_total, p.currency)}</h5></div></div>`);
		}
		d.show();
		summary();
	};

	E.make_quotation = function (name) {
		frappe.model.open_mapped_doc({ method: "erpnext.crm.doctype.opportunity.opportunity.make_quotation", source_name: name });
	};
})();

// ---- Eye CRM · Deal bar: the deal at a glance on top of the Opportunity form, and its stage
// changed from there. Everything it shows comes from the site:
//   stages       the Deals board's active columns, in their order (Kanban › Columns)
//   value        the first Currency field on the board's cards; the other card fields show as facts
//                (Kanban › Customize Cards)
//   process      Eye's pricing, approval and billing fields, when they have a value
// A stage click goes through the same checks as dragging the card (Nexlify Board's popup,
// its confirm screen and Eye's stage check), then the PL before Project Won, then a save.
// Turn the bar off by disabling this Client Script.
(() => {
	const E = window.eye_crm;
	const FIELD = "sales_stage";
	const PROCESS = ["custom_pricing_status", "custom_accounts_approval", "custom_sales_order", "custom_billed_amount",
		"custom_collected_amount"];

	if (!document.getElementById("eye-deal-bar-css")) {
		$(`<style id="eye-deal-bar-css">
			.eye-deal-bar{--bar-accent:#4f46e5;border:1px solid var(--border-color);border-radius:12px;background:var(--card-bg);
				margin:0 24px 18px;padding:18px 26px 16px;box-shadow:0 1px 2px rgba(15,23,42,.04)}
			[data-theme="dark"] .eye-deal-bar{--bar-accent:#818cf8}
			.eye-deal-bar .edb-top{display:flex;align-items:flex-start;gap:24px;flex-wrap:wrap}
			.eye-deal-bar .edb-who{flex:1;min-width:220px}
			.eye-deal-bar .edb-eyebrow{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--text-muted)}
			.eye-deal-bar .edb-title{font-size:20px;font-weight:650;letter-spacing:-.01em;color:var(--heading-color);margin:2px 0 0;
				display:flex;align-items:center;gap:10px;flex-wrap:wrap}
			.eye-deal-bar .edb-value{text-align:right}
			.eye-deal-bar .edb-value b{display:block;font-size:22px;font-weight:650;letter-spacing:-.01em;color:var(--heading-color)}
			.eye-deal-bar .edb-path{display:flex;margin:16px 0 0;overflow-x:auto;padding-bottom:2px}
			.eye-deal-bar .edb-step{flex:1 0 auto;min-width:110px;position:relative;border:0;background:var(--control-bg);
				color:var(--text-muted);font-size:12.5px;font-weight:500;height:34px;padding:0 14px 0 24px;margin-right:3px;
				clip-path:polygon(0 0,calc(100% - 12px) 0,100% 50%,calc(100% - 12px) 100%,0 100%,12px 50%);
				display:flex;align-items:center;justify-content:center;gap:6px;white-space:nowrap;cursor:default}
			.eye-deal-bar .edb-step:first-child{clip-path:polygon(0 0,calc(100% - 12px) 0,100% 50%,calc(100% - 12px) 100%,0 100%);
				border-radius:8px 0 0 8px;padding-left:14px}
			.eye-deal-bar .edb-step:last-child{clip-path:polygon(0 0,100% 0,100% 100%,0 100%,12px 50%);border-radius:0 8px 8px 0;margin-right:0}
			.eye-deal-bar .edb-step.done{background:color-mix(in srgb,var(--bar-accent) 12%,var(--card-bg));color:var(--bar-accent)}
			.eye-deal-bar .edb-step.now{background:var(--step-color,var(--bar-accent));color:#fff;font-weight:600}
			.eye-deal-bar.can-move .edb-step:not(.now){cursor:pointer}
			.eye-deal-bar.can-move .edb-step:not(.now):hover{background:color-mix(in srgb,var(--bar-accent) 22%,var(--card-bg));color:var(--bar-accent)}
			.eye-deal-bar .edb-step svg{width:12px;height:12px}
			.eye-deal-bar .edb-facts{display:flex;flex-wrap:wrap;gap:8px 28px;margin-top:14px;padding-top:12px;border-top:1px solid var(--border-color)}
			.eye-deal-bar .edb-fact{min-width:90px}
			.eye-deal-bar .edb-fact span{display:block;font-size:11px;color:var(--text-muted)}
			.eye-deal-bar .edb-fact b{font-size:13px;font-weight:600;color:var(--text-color)}
			.eye-deal-bar .edb-fact b p{margin:0}
			.eye-deal-bar.busy .edb-path{opacity:.6;pointer-events:none}
		</style>`).appendTo(document.head);
	}

	// the Deals board: which board groups Opportunity by sales_stage, its columns and card fields
	let board_promise = null;
	const board = () =>
		(board_promise =
			board_promise ||
			(async () => {
				try {
					const [row] = await frappe.db.get_list("Kanban Board", {
						filters: { reference_doctype: "Opportunity", field_name: FIELD },
						fields: ["name"],
						order_by: "creation asc",
						limit: 1,
					});
					if (row) {
						const b = await frappe.db.get_doc("Kanban Board", row.name);
						const stages = (b.columns || [])
							.filter((c) => c.status !== "Archived")
							.sort((a, b) => a.idx - b.idx)
							.map((c) => ({ name: c.column_name, color: c.indicator }));
						return { stages, cards: (b.card_fields || []).map((f) => f.fieldname), title: b.title_field };
					}
				} catch (e) {
					console.warn("Eye deal bar: no Deals board", e);
				}
				const stages = await frappe.db.get_list("Sales Stage", { fields: ["name"], order_by: "creation asc", limit: 100 });
				return { stages: stages.map((s) => ({ name: s.name })), cards: [], title: null };
			})());

	const COLORS = { gray: "", grey: "", darkgrey: "var(--gray-700)" };
	const color_of = (c) => {
		const k = String(c || "").toLowerCase();
		return k in COLORS ? COLORS[k] : `var(--${k}-500)`;
	};
	const CHECK = `<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M3 8.5l3.2 3L13 4.5"/></svg>`;

	const can_move = (frm) => !frm.is_new() && frm.doc.docstatus === 0 && frm.perm?.[0]?.write && !frm.get_docfield(FIELD)?.read_only;

	async function render(frm) {
		// only on the real form: Nexlify Board's move popup runs this script on a stand-in form
		const layout = frm.layout && frm.layout.wrapper;
		if (!layout || typeof layout !== "object") return;
		let $bar = $(layout).children(".eye-deal-bar");
		if (frm.is_new()) return $bar.remove();
		if (!$bar.length) $bar = $(`<div class="eye-deal-bar"></div>`).prependTo(layout);

		const b = await board();
		const doc = frm.doc;
		const meta = frappe.get_meta("Opportunity");
		const df = (f) => meta.fields.find((d) => d.fieldname === f);
		const show = (f) => frappe.format(doc[f], df(f), { inline: true }, doc);

		const stages = [...b.stages];
		const now = doc[FIELD];
		if (now && !stages.some((s) => s.name === now)) stages.unshift({ name: now });
		const at = stages.findIndex((s) => s.name === now);
		const path = stages
			.map((s, i) => {
				const cls = i === at ? "now" : i < at ? "done" : "";
				const c = i === at ? color_of(s.color) : "";
				return `<button type="button" class="edb-step ${cls}" data-stage="${E.esc(s.name)}"
					${c ? `style="--step-color:${c}"` : ""} title="${E.esc(i === at ? __("Current stage") : __("Move to {0}", [__(s.name)]))}">
					${i < at ? CHECK : ""}${E.esc(__(s.name))}</button>`;
			})
			.join("");

		const cards = b.cards.filter((f) => df(f) && f !== b.title);
		const money = cards.find((f) => ["Currency"].includes(df(f).fieldtype));
		const facts = [...cards.filter((f) => f !== money), ...PROCESS.filter((f) => df(f) && !cards.includes(f))]
			.filter((f) => doc[f] !== undefined && doc[f] !== null && doc[f] !== "" && doc[f] !== 0)
			.map((f) => `<div class="edb-fact"><span>${E.esc(__(df(f).label))}</span><b>${show(f)}</b></div>`)
			.join("");

		const title = (b.title && doc[b.title]) || doc.customer_name || doc.title || doc.party_name || doc.name;
		const [status, scolor] = frappe.get_indicator(doc, "Opportunity") || [];
		$bar.toggleClass("can-move", !!can_move(frm)).html(`
			<div class="edb-top">
				<div class="edb-who">
					<div class="edb-eyebrow">${E.esc(doc.name)}${doc.opportunity_owner ? " · " + E.esc(frappe.user.full_name(doc.opportunity_owner)) : ""}</div>
					<div class="edb-title">${E.esc(title)}
						${status ? `<span class="indicator-pill ${E.esc(scolor)}">${E.esc(__(status))}</span>` : ""}</div>
				</div>
				${money ? `<div class="edb-value"><span class="edb-eyebrow">${E.esc(__(df(money).label))}</span><b>${show(money)}</b></div>` : ""}
			</div>
			<div class="edb-path">${path}</div>
			${facts ? `<div class="edb-facts">${facts}</div>` : ""}`);

		$bar.find(".edb-step:not(.now)").on("click", function () {
			if (can_move(frm)) move(frm, this.dataset.stage, $bar);
		});
	}

	// the same PL screen as the form and the board (eye.pricing pl_view)
	async function confirm_pl(frm) {
		const r = await E.api("pl_view", { name: frm.doc.name });
		return new Promise((resolve) => {
			let ok = false;
			const d = new frappe.ui.Dialog({
				title: __("PL before Project Won"),
				size: "extra-large",
				primary_action_label: __("Confirm → Project Won"),
				primary_action() {
					ok = true;
					d.hide();
				},
				secondary_action_label: __("Cancel"),
				secondary_action: () => d.hide(),
			});
			d.onhide = () => resolve(ok);
			$(d.body).html(r.html);
			d.show();
		});
	}

	async function move(frm, to, $bar) {
		$bar.addClass("busy");
		try {
			if (frm.is_dirty()) await frm.save();
			const name = frm.doc.name;
			const from = frm.doc[FIELD];
			let values = {};
			const ask = window.nexlify?.board?.ask_move;
			if (ask) {
				const answer = await ask("Opportunity", name, FIELD, to);
				if (answer === null) return;
				if (answer === "form") {
					// what's missing can only be filled here: the stage is set, the form marks the fields
					frm.__eye_prev_stage = to;
					await frm.set_value(FIELD, to);
					frappe.show_alert({ message: __("Fill the marked fields, then save"), indicator: "orange" }, 6);
					return;
				}
				values = answer || {};
			} else if (!(await E.check_deal_move(name, to))) {
				return;
			}
			if (to === "Project Won" && !E.WON.includes(from) && !(await confirm_pl(frm))) return;
			frm.__eye_prev_stage = to; // the form's own stage check already ran above
			await frm.set_value({ ...values, [FIELD]: to });
			await frm.save().catch(() => frm.reload_doc());
		} finally {
			$bar.removeClass("busy");
		}
	}

	frappe.ui.form.on("Opportunity", {
		refresh: (frm) => render(frm),
		[FIELD]: (frm) => setTimeout(() => render(frm), 50),
	});
})();

// ---- Eye CRM desk helpers (the same block opens every Eye Client Script; the newest wins) ----
// Eye checks its own stages on the server (eye.pricing, eye.billing); these helpers show what a
// move needs and offer the dialogs that fix it. Buttons in messages follow the data-nx-action
// convention, so they work with or without Nexlify Board installed.
(() => {
	const VERSION = 6;
	if (window.eye_crm && window.eye_crm.version >= VERSION) return;
	const E = (window.eye_crm = { version: VERSION });

	E.STAGES = ["Estimation", "Proposal", "Quotation", "Project Won", "Accounts, please approve", "Quote approved"];
	E.WON = ["Project Won", "Accounts, please approve", "Quote approved"];
	E.ACCOUNTS_STAGE = "Accounts, please approve";
	E.APPROVED_STAGE = "Quote approved";
	E.BILLING_STAGES = ["To be invoiced", "Finance, please issue", "Invoiced", "Collected"];

	E.call = (method, op, args = {}, opts = {}) =>
		frappe.call({ method, args: { op, ...args }, ...opts }).then((r) => r.message && r.message.result);
	E.api = (op, args, opts) => E.call("eye.pricing", op, args, opts);
	E.billing = (op, args, opts) => E.call("eye.billing", op, args, opts);
	E.money = (v, cur) => format_currency(flt(v), cur);
	E.esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
	E.is_sales = () => frappe.user.has_role(["Sales User", "Sales Manager"]);
	E.is_accounts = () => frappe.user.has_role(["Accounts User", "Accounts Manager", "Sales Manager", "System Manager"]);
	E.is_finance = () => frappe.user.has_role(["Accounts User", "Accounts Manager", "System Manager"]);
	E.refresh = () => {
		if (window.cur_frm && !cur_frm.is_new()) return cur_frm.reload_doc();
		window.cur_list?.board?.refresh?.();
		window.cur_list?.refresh?.();
	};

	// ---- action buttons: <button data-nx-action="NAME" data-doctype=".." data-name="..">
	window.nx_actions = window.nx_actions || {};
	const ctx_of = (el) => {
		const frm = window.cur_frm;
		const moving = window.nx_action_context;
		const doctype = el?.dataset.doctype || moving?.doctype || frm?.doctype;
		const name = el?.dataset.name || moving?.name || frm?.docname;
		const form = frm && frm.doctype === doctype && frm.docname === name ? frm : null;
		return { doctype, name, frm: form, refresh: E.refresh };
	};
	if (!window.nx_run_action) {
		window.nx_run_action = (action, ctx) => {
			action = (action || "").trim();
			if (!action) return;
			if (action === "form") return frappe.set_route("Form", ctx.doctype, ctx.name);
			if (action.startsWith("route:")) return frappe.set_route(action.slice(6).replace(/^\/app\//, ""));
			if (action.startsWith("map:")) {
				const method = action.slice(4);
				return ctx.frm
					? frappe.model.open_mapped_doc({ method, frm: ctx.frm })
					: frappe.model.open_mapped_doc({ method, source_name: ctx.name });
			}
			const fn = window.nx_actions[action];
			if (!fn) return frappe.set_route("Form", ctx.doctype, ctx.name);
			return fn(ctx);
		};
	}
	if (!window.__nx_action_click) {
		window.__nx_action_click = true;
		$(document).on("click", "[data-nx-action]", function (e) {
			e.preventDefault();
			const ctx = ctx_of(this);
			$(this).closest(".modal").modal("hide");
			window.nx_run_action(this.dataset.nxAction, ctx);
		});
	}
	Object.assign(window.nx_actions, {
		requirements: (ctx) => (ctx.frm ? ctx.frm.scroll_to_field("custom_requirements") : E.requirements_dialog(ctx.name, ctx.refresh)),
		margin: (ctx) => (ctx.frm ? ctx.frm.scroll_to_field("custom_costing") : E.margin_dialog(ctx.name, ctx.refresh)),
		invoice: (ctx) => E.invoiced_dialog(ctx.name, ctx.refresh),
		collected: (ctx) => E.collected_dialog(ctx.name, ctx.refresh),
	});

	// ---- a blocked move (Nexlify Board shows its own screen when it is installed)
	E.steps_html = (doctype, name, missing) => {
		const rows = missing
			.map((s) => `<li>${E.esc(s.label)}${s.waiting_on ? ` <span class="text-muted">(${__("waiting on {0}", [E.esc(s.waiting_on)])})</span>` : ""}</li>`)
			.join("");
		const first = missing.find((s) => s.action && !s.waiting_on);
		const button = first
			? `<button class="btn btn-xs btn-primary" data-nx-action="${E.esc(first.action)}" data-doctype="${E.esc(doctype)}" data-name="${E.esc(name)}">${E.esc(first.action_label || __("Open"))}</button>`
			: "";
		return `<ul>${rows}</ul>${button}`;
	};
	E.blocked = (doctype, name, to, html) => {
		window.nx_action_context = { doctype, name };
		frappe.msgprint({ title: __("Can't move to {0} yet", [__(to)]), indicator: "red", message: html });
	};
	E.check_deal_move = async (name, to) => {
		const r = await E.api("stage_check", { name, to });
		if (!r.error && !(r.missing || []).length) return true;
		E.blocked("Opportunity", name, to, r.message || E.esc(r.error));
		return false;
	};

	// ---- Accounts' answer
	E.approve_dialog = (name, after) =>
		frappe.prompt(
			{ fieldtype: "Small Text", fieldname: "note", label: __("Note (optional)") },
			(v) =>
				E.api("approve_project", { name, note: v.note }, { freeze: true }).then((r) => {
					frappe.show_alert({
						message: r.sales_order ? __("Approved: Sales Order {0}", [r.sales_order]) : __("Approved"),
						indicator: "green",
					});
					if (r.error) frappe.msgprint({ title: __("Sales Order not created"), indicator: "orange", message: E.esc(r.error) });
					after && after();
				}),
			__("Approve the project"),
			__("Approve")
		);
	E.reject_dialog = (name, after) =>
		frappe.prompt(
			{ fieldtype: "Small Text", fieldname: "reason", label: __("Why isn't it approved?"), reqd: 1 },
			(v) =>
				E.api("reject_project", { name, reason: v.reason }, { freeze: true }).then(() => {
					frappe.show_alert({ message: __("Sent back to Project Won"), indicator: "orange" });
					after && after();
				}),
			__("Send back to Sales"),
			__("Send Back")
		);
	E.retry_sales_order = (name, after) =>
		E.api("make_sales_order", { name }, { freeze: true }).then((so) => {
			frappe.show_alert({ message: __("Sales Order {0}", [so]), indicator: "green" });
			after && after();
		});

	// ---- invoices
	E.request_invoice_dialog = async (opportunity, after) => {
		const so = await E.billing("so_lines", { opportunity });
		const rows = so.rows.filter((r) => r.left > 0.0001).map((r) => ({ ...r, bill: r.left }));
		if (!rows.length) return frappe.msgprint(__("Everything on Sales Order {0} is already requested.", [so.sales_order]));
		const d = new frappe.ui.Dialog({
			title: __("Request an invoice"),
			size: "large",
			fields: [
				{ fieldtype: "Date", fieldname: "expected_date", label: __("Expected invoice date"), reqd: 1, default: frappe.datetime.get_today() },
				{ fieldtype: "Column Break" },
				{ fieldtype: "Small Text", fieldname: "notes", label: __("Notes for Finance") },
				{ fieldtype: "Section Break", label: __("Items from {0}", [so.sales_order]) },
				{
					fieldtype: "Table",
					fieldname: "rows",
