	// the PL is drawn on the server (eye.pricing pl_view), so the form shows the same screen
	E.pl_dialog = async function (name) {
		const r = await E.api("pl_view", { name });
		return new Promise((resolve) => {
			let done = false;
			const d = new frappe.ui.Dialog({
				title: __("PL before Project Won"),
				size: "extra-large",
				primary_action_label: __("Confirm → Project Won"),
				primary_action() {
					done = true;
					d.hide();
					resolve(true);
				},
				secondary_action_label: __("Cancel"),
				secondary_action: () => d.hide(),
				onhide: () => {
					if (!done) resolve(false);
