// ---- Eye CRM desk helpers (the same block opens every Eye Client Script; the newest wins) ----
// Eye checks its own stages on the server (eye.pricing, eye.billing); these helpers show what a
// move needs and offer the dialogs that fix it. Buttons in messages follow the data-nx-action
// convention, so they work with or without Nexlify Board installed.
(() => {
	const VERSION = 6;
	if (window.eye_crm && window.eye_crm.version >= VERSION) return;
	const E = (window.eye_crm = { version: VERSION });

	E.STAGES = ["Estimation", "Proposal", "Quotation", "Project Won", "Accounts, please approve", "Quote approved"];
	E.WON = ["Project Won", "Accounts, please approve", "Quote approved"];
	E.ACCOUNTS_STAGE = "Accounts, please approve";
	E.APPROVED_STAGE = "Quote approved";
	E.BILLING_STAGES = ["To be invoiced", "Finance, please issue", "Invoiced", "Collected"];

	E.call = (method, op, args = {}, opts = {}) =>
		frappe.call({ method, args: { op, ...args }, ...opts }).then((r) => r.message && r.message.result);
	E.api = (op, args, opts) => E.call("eye.pricing", op, args, opts);
	E.billing = (op, args, opts) => E.call("eye.billing", op, args, opts);
	E.money = (v, cur) => format_currency(flt(v), cur);
	E.esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
	E.is_sales = () => frappe.user.has_role(["Sales User", "Sales Manager"]);
	E.is_accounts = () => frappe.user.has_role(["Accounts User", "Accounts Manager", "Sales Manager", "System Manager"]);
	E.is_finance = () => frappe.user.has_role(["Accounts User", "Accounts Manager", "System Manager"]);
	E.refresh = () => {
		if (window.cur_frm && !cur_frm.is_new()) return cur_frm.reload_doc();
		window.cur_list?.board?.refresh?.();
		window.cur_list?.refresh?.();
	};

	// ---- action buttons: <button data-nx-action="NAME" data-doctype=".." data-name="..">
	window.nx_actions = window.nx_actions || {};
	const ctx_of = (el) => {
		const frm = window.cur_frm;
		const moving = window.nx_action_context;
		const doctype = el?.dataset.doctype || moving?.doctype || frm?.doctype;
		const name = el?.dataset.name || moving?.name || frm?.docname;
		const form = frm && frm.doctype === doctype && frm.docname === name ? frm : null;
		return { doctype, name, frm: form, refresh: E.refresh };
	};
	if (!window.nx_run_action) {
		window.nx_run_action = (action, ctx) => {
			action = (action || "").trim();
			if (!action) return;
			if (action === "form") return frappe.set_route("Form", ctx.doctype, ctx.name);
			if (action.startsWith("route:")) return frappe.set_route(action.slice(6).replace(/^\/app\//, ""));
			if (action.startsWith("map:")) {
				const method = action.slice(4);
				return ctx.frm
					? frappe.model.open_mapped_doc({ method, frm: ctx.frm })
					: frappe.model.open_mapped_doc({ method, source_name: ctx.name });
			}
			const fn = window.nx_actions[action];
			if (!fn) return frappe.set_route("Form", ctx.doctype, ctx.name);
			return fn(ctx);
		};
	}
	if (!window.__nx_action_click) {
		window.__nx_action_click = true;
		$(document).on("click", "[data-nx-action]", function (e) {
			e.preventDefault();
			const ctx = ctx_of(this);
			$(this).closest(".modal").modal("hide");
			window.nx_run_action(this.dataset.nxAction, ctx);
		});
	}
	Object.assign(window.nx_actions, {
		requirements: (ctx) => (ctx.frm ? ctx.frm.scroll_to_field("custom_requirements") : E.requirements_dialog(ctx.name, ctx.refresh)),
		margin: (ctx) => (ctx.frm ? ctx.frm.scroll_to_field("custom_costing") : E.margin_dialog(ctx.name, ctx.refresh)),
		invoice: (ctx) => E.invoiced_dialog(ctx.name, ctx.refresh),
		collected: (ctx) => E.collected_dialog(ctx.name, ctx.refresh),
	});

	// ---- a blocked move (Nexlify Board shows its own screen when it is installed)
	E.steps_html = (doctype, name, missing) => {
		const rows = missing
			.map((s) => `<li>${E.esc(s.label)}${s.waiting_on ? ` <span class="text-muted">(${__("waiting on {0}", [E.esc(s.waiting_on)])})</span>` : ""}</li>`)
			.join("");
		const first = missing.find((s) => s.action && !s.waiting_on);
		const button = first
			? `<button class="btn btn-xs btn-primary" data-nx-action="${E.esc(first.action)}" data-doctype="${E.esc(doctype)}" data-name="${E.esc(name)}">${E.esc(first.action_label || __("Open"))}</button>`
			: "";
		return `<ul>${rows}</ul>${button}`;
	};
	E.blocked = (doctype, name, to, html) => {
		window.nx_action_context = { doctype, name };
		frappe.msgprint({ title: __("Can't move to {0} yet", [__(to)]), indicator: "red", message: html });
